	private class StubPluginInstaller : PluginInstaller {

		private List<Plugin> loadedPlugins = new();
		private Set<string> addedPlugins = new();
		private Set<string> removedPlugins = new();

		/* @Override */
		public void addPlugins(List<string> pluginClassNames)
    {
			foreach (string name in pluginClassNames) {
				addedPlugins.add(name);
				runSwing(() => loadPlugin(name));
			}
		}

		private void loadPlugin(string name) {
			try {
				Class<Plugin> clazz =
					ClassSearcher.forNameSafe(name, typeof(Plugin), getClass().getClassLoader());
				Plugin plugin = clazz.getDeclaredConstructor(typeof(PluginTool)).newInstance(tool);
				loadedPlugins.add(plugin);
			}
			catch (Exception e) {
				failWithException("Unable to load plugin: " + name, e);
			}
		}

		/* @Override */
		public void removePlugins(List<Plugin> array) {
			foreach (Plugin plugin in array) {
				loadedPlugins.remove(plugin);
				removedPlugins.remove(plugin.GetType().getSimpleName());
			}
		}

		/* @Override */
		public List<Plugin> getManagedPlugins() {
			return loadedPlugins;
		}

		Set<string> getAddedPlugins() {
			return addedPlugins;
		}
	}

	private class StubPluginPackagingProvider : PluginPackagingProvider {

		private List<PluginPackage> packages = new();
		private List<PluginDescription> descriptions = new();
		private List<PluginDescription> unstableDescriptions = new();

		/* @Override */
		public List<PluginPackage> getPluginPackages() {
			return packages;
		}

		void addPackage(PluginPackage p) {
			packages.add(p);
		}

		/* @Override */
		public List<PluginDescription> getPluginDescriptions() {
			return descriptions;
		}

		void addDescription(PluginDescription pd) {
			descriptions.add(pd);
		}

		/* @Override */
		public PluginDescription getPluginDescription(string pluginClassName) {
			List<PluginDescription> results = descriptions.stream()
					.filter(pd => pd.getPluginClass().getName().equals(pluginClassName))
					.collect(Collectors.toList());
			assertEquals(1, results.size());
			return results.get(0);
		}

		/* @Override */
		public List<PluginDescription> getPluginDescriptions(PluginPackage pluginPackage) {
			List<PluginDescription> results = descriptions.stream()
					.filter(pd => pd.getPluginPackage().equals(pluginPackage))
					.collect(Collectors.toList());
			assertThat(results, not(empty()));
			return results;
		}

		/* @Override */
		public PluginPackage getUnstablePluginPackage() {
			return UNSTABLE_PACKAGE;
		}

		/* @Override */
		public List<PluginDescription> getUnstablePluginDescriptions() {
			return unstableDescriptions;
		}
	}

